// ═══════════════════════════════════════════════════════════════════════════════
// ZONE COMPATIBILITY MATRIX - Mely zónák kombinálhatók egy napon?
// ═══════════════════════════════════════════════════════════════════════════════

const ZONE_COMPATIBILITY = {
    // Magyar zónák - EGY NAP = EGY FŐ RÉGIÓ
    "GYOR_PAPA":          ["GYOR_PAPA"],                    // Csak önmagával
    "SOPRON_HATARMENTI":  ["SOPRON_HATARMENTI", "AT_BURGENLAND_NORD"],  // + osztrák határ
    "SZOMBATHELY_VAS":    ["SZOMBATHELY_VAS", "AT_BURGENLAND_SUED"],    // + osztrák határ
    "BALATON":            ["BALATON"],                      // Csak önmagával - nagy terület!
    "SZEKESFEHERVAR":     ["SZEKESFEHERVAR"],               // Csak önmagával

    // Osztrák határ menti (HU rendszerből)
    "AT_BURGENLAND_NORD": ["AT_BURGENLAND_NORD", "SOPRON_HATARMENTI"],
    "AT_BURGENLAND_SUED": ["AT_BURGENLAND_SUED", "SZOMBATHELY_VAS"],

    // Osztrák belső - CSAK önmagukkal (HU-val NEM kompatibilis!)
    "WIEN":     ["WIEN"],
    "LINZ":     ["LINZ"],
    "GRAZ":     ["GRAZ"],
    "KAERNTEN": ["KAERNTEN"],
    "WEST":     ["WEST"]
};

// ═══════════════════════════════════════════════════════════════════════════════
// HELPER FUNCTIONS
// ═══════════════════════════════════════════════════════════════════════════════

function extractZipCode(address) {
    if (!address) return null;
    const match = address.match(/\b(\d{4})\b/);
    return match ? match[1] : null;
}

function getCluster(address) {
    if (!address) return "UNKNOWN";

    const normalized = address.toLowerCase().trim();
    const zipCode = extractZipCode(address);

    console.log('🔍 getCluster analyzing:', { address: normalized, zipCode });

    // FONTOS: Ország detektálás először!
    const isAustria = normalized.includes('österreich') || 
                      normalized.includes('austria') || 
                      normalized.includes(', at') ||
                      normalized.includes(' at-') ||
                      // Osztrák városok
                      normalized.includes('wien') ||
                      normalized.includes('eisenstadt') ||
                      normalized.includes('oberwart');

    const isHungary = normalized.includes('magyarország') || 
                      normalized.includes('hungary') || 
                      normalized.includes('ungarn') ||
                      normalized.includes(', hu') ||
                      // Magyar városok egyértelmű jelei
                      normalized.includes('győr') ||
                      normalized.includes('gyor') ||
                      normalized.includes('budapest') ||
                      normalized.includes('balaton') ||
                      normalized.includes('megye');

    // ELSŐ KÍSÉRLET: Városnév alapján (legmegbízhatóbb!)
    for (const [clusterId, cluster] of Object.entries(GEO_CLUSTERS)) {
        if (cluster.cities && cluster.cities.some(city => normalized.includes(city))) {
            console.log(`  → Matched by city name: ${clusterId}`);
            return clusterId;
        }
    }

    // MÁSODIK KÍSÉRLET: Irányítószám alapján (ország-ellenőrzéssel!)
    if (zipCode) {
        const prefix = zipCode.substring(0, 2);

        for (const [clusterId, cluster] of Object.entries(GEO_CLUSTERS)) {
            if (cluster.zipPrefixes && cluster.zipPrefixes.includes(prefix)) {
                // Ha tudjuk az országot, csak akkor fogadjuk el ha egyezik
                if (isAustria && cluster.country === "HU") continue;
                if (isHungary && cluster.country === "AT") continue;

                console.log(`  → Matched by ZIP prefix ${prefix}: ${clusterId}`);
                return clusterId;
            }
        }
    }

    console.log('  → No match found, returning UNKNOWN');
    return "UNKNOWN";
}

function areZonesCompatible(zone1, zone2) {
    if (zone1 === "UNKNOWN" || zone2 === "UNKNOWN") return true;  // Benefit of doubt

    const compatible = ZONE_COMPATIBILITY[zone1] || [];
    return compatible.includes(zone2);
}

function getTravelBuffer(zone1, zone2) {
    if (zone1 === zone2) return TRAVEL_BUFFER_SAME_ZONE;

    // Cross-border (AT-HU)
    const z1Country = GEO_CLUSTERS[zone1]?.country;
    const z2Country = GEO_CLUSTERS[zone2]?.country;
    if (z1Country !== z2Country) return TRAVEL_BUFFER_CROSS_BORDER;

    // Same country, different zone = neighbor
    return TRAVEL_BUFFER_NEIGHBOR;
}

function getClusterName(clusterId) {
    return GEO_CLUSTERS[clusterId]?.name || "Ismeretlen";
}

function timeToMinutes(timeStr) {
    const [h, m] = timeStr.split(':').map(Number);
    return h * 60 + m;
}

function minutesToTime(totalMinutes) {
    const h = Math.floor(totalMinutes / 60);
    const m = totalMinutes % 60;
    return `${h.toString().padStart(2, '0')}:${m.toString().padStart(2, '0')}`;
}

function addMinutes(timeStr, minutesToAdd) {
    return minutesToTime(timeToMinutes(timeStr) + minutesToAdd);
}

// ═══════════════════════════════════════════════════════════════════════════════
// MAIN LOGIC
// ═══════════════════════════════════════════════════════════════════════════════

const reqCluster = getCluster(newBooking.location);
const serviceDuration = parseInt(newBooking.duration) || 60;
const totalRequiredTime = serviceDuration + SETUP_TIME;

console.log('🗺️ Cluster Detection Result:', {
    requestedCluster: reqCluster,
    clusterName: getClusterName(reqCluster),
    location: newBooking.location
});

// ═══════════════════════════════════════════════════════════════════════════════
// SCENARIO 1: EMPTY DAY (ANCHOR BOOKING)
// ═══════════════════════════════════════════════════════════════════════════════
if (existingEvents.length === 0) {
    let startTime = newBooking.slotStartTime || "09:00";
    const endTime = addMinutes(startTime, serviceDuration);

    console.log('✅ Empty day - Anchor booking for zone:', reqCluster);

    return [{
        json: {
            available: true,
            status: "ANCHOR_BOOKING",
            slot: {
                date: newBooking.date,
                startTime: startTime,
                endTime: endTime
            },
            cluster: {
                id: reqCluster,
                name: getClusterName(reqCluster),
                country: GEO_CLUSTERS[reqCluster]?.country || "?"
            },
            calendar: {
                isAnchor: true,
                dayStatus: "EMPTY",
                internalEndTime: addMinutes(startTime, totalRequiredTime)
            },
            message: `Tökéletes! ${newBooking.date} szabad. Ön lesz az első ügyfél a ${getClusterName(reqCluster)} régióban.`,
            booking: newBooking,
            __axr_input: __axrInput
        }
    }];
}

// ═══════════════════════════════════════════════════════════════════════════════
// SCENARIO 2: CHECK GEO-ZONE COMPATIBILITY (EGY NAP = EGY RÉGIÓ)
// ═══════════════════════════════════════════════════════════════════════════════
const firstEvent = existingEvents[0].json;
const eventLocation = firstEvent.location || firstEvent.summary || "";
const dayCluster = getCluster(eventLocation);

console.log('🔍 Zone Compatibility Check:', {
    dayCluster: dayCluster,
    dayClusterName: getClusterName(dayCluster),
    requestedCluster: reqCluster,
    requestedClusterName: getClusterName(reqCluster),
    compatible: areZonesCompatible(dayCluster, reqCluster)
});

if (!areZonesCompatible(dayCluster, reqCluster)) {
    const dayClusterName = getClusterName(dayCluster);
    const reqClusterName = getClusterName(reqCluster);

    console.log('❌ Zone incompatible!');

    let message = `Ez a nap már le van foglalva a "${dayClusterName}" régióra. Az Ön helyszíne („${reqClusterName}") túl messze van ahhoz, hogy egy napon belül kombinálható legyen.`;

    // Special message for Balaton
    if (reqCluster === "BALATON" || dayCluster === "BALATON") {
        message = `A Balaton régió nagy kiterjedése miatt csak Balaton-környéki megrendelésekkel kombinálható egy napon. Kérjük válasszon másik napot!`;
    }

    return [{
        json: {
            available: false,
            error: "ZONE_INCOMPATIBLE",
            message: message,
            details: {
                dayZone: dayCluster,
                dayZoneName: dayClusterName,
                requestedZone: reqCluster,
                requestedZoneName: reqClusterName,
                reason: "DISTANCE_TOO_FAR"
            },
            suggestion: {
                message: "Kérjük válasszon másik napot!",
                action: "SHOW_ALTERNATIVE_DATES"
            },
            __axr_input: __axrInput
        }
    }];
}

// ═══════════════════════════════════════════════════════════════════════════════
// SCENARIO 3: CHECK TIME AVAILABILITY WITH DYNAMIC TRAVEL BUFFER
// ═══════════════════════════════════════════════════════════════════════════════

const selectedStartTime = newBooking.slotStartTime || "09:00";
const selectedStartMinutes = timeToMinutes(selectedStartTime);

// Calculate appropriate travel buffer based on zones
const travelBuffer = getTravelBuffer(dayCluster, reqCluster);

console.log('⏰ Time Slot Analysis:', {
    requestedStart: selectedStartTime,
    existingEventsCount: existingEvents.length,
    travelBuffer: travelBuffer
});

let actualStartTime = selectedStartTime;
let hasConflict = false;

for (const event of existingEvents) {
    if (!event.json.start?.dateTime || !event.json.end?.dateTime) continue;

    const eventStart = new Date(event.json.start.dateTime);
    const eventEnd = new Date(event.json.end.dateTime);
    const eventStartMinutes = eventStart.getHours() * 60 + eventStart.getMinutes();
    const eventEndMinutes = eventEnd.getHours() * 60 + eventEnd.getMinutes();

    console.log('  → Checking event:', {
        summary: event.json.summary,
        slot: `${minutesToTime(eventStartMinutes)} - ${minutesToTime(eventEndMinutes)}`
    });

    // Check overlap with travel buffer
    const requestedEnd = selectedStartMinutes + totalRequiredTime;

    if (selectedStartMinutes < eventEndMinutes + travelBuffer && 
        requestedEnd > eventStartMinutes - travelBuffer) {

        const newStart = eventEndMinutes + travelBuffer;
        if (newStart > timeToMinutes(actualStartTime)) {
            actualStartTime = minutesToTime(newStart);
            hasConflict = true;
            console.log(`  ⚠️ Conflict! Adjusted start to: ${actualStartTime}`);
        }
    }
}

const earliestStart = actualStartTime;
const projectedFinish = addMinutes(earliestStart, totalRequiredTime);

console.log('📊 Final Time Calculation:', {
    earliestStart: earliestStart,
    projectedFinish: projectedFinish,
    workEnd: WORK_END
});

// Check Hard Stop at 17:00
if (timeToMinutes(projectedFinish) > timeToMinutes(WORK_END)) {
    const availableMinutes = timeToMinutes(WORK_END) - timeToMinutes(earliestStart) - SETUP_TIME;

    console.log('❌ Day full - exceeds 17:00');

    return [{
        json: {
            available: false,
            error: "DAY_FULL",
            message: `Sajnos ez a munka már nem fér bele a napi programba. A legkorábbi kezdés ${earliestStart} lenne, de a munka ${projectedFinish}-ig tartana (munkaidő vége: ${WORK_END}).`,
            details: {
                earliestPossibleStart: earliestStart,
                requiredTime: totalRequiredTime,
                projectedFinish: projectedFinish,
                availableTime: Math.max(0, availableMinutes),
                workEnd: WORK_END,
                travelBufferUsed: travelBuffer
            },
            suggestion: {
                message: "Kérjük válasszon másik napot!",
                action: "SHOW_NEXT_AVAILABLE"
            },
            __axr_input: __axrInput
        }
    }];
}

// ═══════════════════════════════════════════════════════════════════════════════
// SUCCESS - SLOT AVAILABLE
// ═══════════════════════════════════════════════════════════════════════════════
const clientEndTime = addMinutes(earliestStart, serviceDuration);

console.log('✅ Slot available!', {
    startTime: earliestStart,
    endTime: clientEndTime,
    cluster: reqCluster
});

return [{
    json: {
        available: true,
        status: hasConflict ? "SLOT_ADJUSTED" : "SLOT_AVAILABLE",
        slot: {
            date: newBooking.date,
            startTime: earliestStart,
            endTime: clientEndTime
        },
        cluster: {
            id: reqCluster,
            name: getClusterName(reqCluster),
            country: GEO_CLUSTERS[reqCluster]?.country || "?"
        },
        calendar: {
            isAnchor: false,
            dayStatus: "PARTIALLY_BOOKED",
            dayZone: dayCluster,
            existingBookings: existingEvents.length,
            internalEndTime: projectedFinish,
            travelBufferApplied: travelBuffer
        },
        message: hasConflict 
            ? `${newBooking.date} napon ${earliestStart} órakor tudunk érkezni (más foglalások + ${travelBuffer} perc utazási idő miatt módosítva).`
            : `Szuper! ${newBooking.date} napon ${earliestStart} órakor tudunk menni.`,
        booking: newBooking,
            __axr_input: __axrInput
        }
    }];

