    logic_hash: 'sha256:9a31f43fddd0107710ef07bdab54bc9efcc5ddc97817ef444cdfb5244f6bfec3' },
  { node: 'Fresh Calendar Check',   readFrom: 'AXR Mark: Fresh Calendar Check',
